/** A self-contained read-only snapshot. It contains campaign content, never account/session data. */
async function makeShareUrl(campaign) {
	const product = { ...campaign.product };
	if (product.photoUrl?.startsWith("data:") || product.photoUrl?.startsWith("blob:")) delete product.photoUrl;
	else if (product.photoUrl) product.photoUrl = new URL(product.photoUrl, window.location.origin).href;
	const snapshot = campaignSchema.parse({
		...campaign,
		product
	});
	const bytes = new TextEncoder().encode(JSON.stringify(snapshot));
	let binary = "";
	for (const byte of bytes) binary += String.fromCharCode(byte);
	const encoded = btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
	return `${window.location.origin}/share/${encodeURIComponent(campaign.id)}#data=${encoded}`;
}
function readSharedCampaign() {
	const value = new URLSearchParams(window.location.hash.slice(1)).get("data");
	if (!value || value.length > 2e5) return null;
	try {
		const binary = atob(value.replace(/-/g, "+").replace(/_/g, "/"));
		const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
		const parsed = campaignSchema.safeParse(JSON.parse(new TextDecoder().decode(bytes)));
		if (!parsed.success || !Number.isFinite(new Date(parsed.data.createdAt).getTime())) return null;
		const url = parsed.data.product.photoUrl;
		if (url && !/^https?:\/\//i.test(url) && !url.startsWith("/")) delete parsed.data.product.photoUrl;
		return parsed.data;
	} catch {
		return null;
	}
}
